const APP_URL='http://127.0.0.1:3010/#today';
const DEBUG_PORT=9344;
async function websocketText(data){if(typeof data==='string')return data;if(data&&typeof data.text==='function')return data.text();if(data instanceof ArrayBuffer)return new TextDecoder().decode(data);if(ArrayBuffer.isView(data))return new TextDecoder().decode(data);return String(data);}
class CdpClient{
  constructor(url){this.url=url;this.nextId=1;this.pending=new Map();this.listeners=new Map();}
  async connect(){this.socket=new WebSocket(this.url);await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('CDP open timeout')),8000);this.socket.addEventListener('open',()=>{clearTimeout(timer);resolve();},{once:true});this.socket.addEventListener('error',()=>reject(new Error('CDP error')),{once:true});});this.socket.addEventListener('message',async event=>{const message=JSON.parse(await websocketText(event.data));if(message.id){const pending=this.pending.get(message.id);if(!pending)return;this.pending.delete(message.id);clearTimeout(pending.timer);if(message.error)pending.reject(new Error(message.error.message));else pending.resolve(message.result||{});return;}for(const listener of this.listeners.get(message.method)||[])listener(message.params||{});});}
  on(method,listener){const list=this.listeners.get(method)||[];list.push(listener);this.listeners.set(method,list);}
  send(method,params={},timeoutMs=12_000){const id=this.nextId++;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending.delete(id);reject(new Error(`CDP timeout: ${method}`));},timeoutMs);this.pending.set(id,{resolve,reject,timer});this.socket.send(JSON.stringify({id,method,params}));});}
  close(){try{this.socket?.close();}catch{}}
}

async function verifyProductionPreviewAbsence(){
  await withBrowserHarness({name:'IELTS production preview containment',profilePrefix:'vocab-ielts-preview-',ports:[3010,DEBUG_PORT]},async({browser:browserInfo,profileDir,spawnTracked})=>{
    let serverOutput='';let browserOutput='';let cdp;
    const serverRecord=spawnTracked('IELTS production preview server',process.execPath,['node_modules/vite/bin/vite.js','preview','--host','127.0.0.1','--port','3010','--strictPort'],{stdio:['ignore','pipe','pipe'],env:{...process.env,NODE_ENV:'production'}});
    serverRecord.child.stdout.on('data',chunk=>serverOutput+=chunk);serverRecord.child.stderr.on('data',chunk=>serverOutput+=chunk);
    try{
      await waitForHttp(APP_URL,{processRecord:serverRecord,label:'IELTS production preview server'});
      const browserRecord=spawnTracked('IELTS production preview browser',browserInfo.path,browserLaunchArguments({profileDir,debugPort:DEBUG_PORT,appUrl:APP_URL,extra:['--enable-automation']}),{stdio:['ignore','pipe','pipe']});
      browserRecord.child.stdout.on('data',chunk=>browserOutput+=chunk);browserRecord.child.stderr.on('data',chunk=>browserOutput+=chunk);
      await waitForHttp(`http://127.0.0.1:${DEBUG_PORT}/json/version`,{processRecord:browserRecord,label:'IELTS production preview browser CDP'});
      let target;for(let attempt=0;attempt<100&&!target;attempt++){const targets=await(await fetch(`http://127.0.0.1:${DEBUG_PORT}/json/list`)).json();target=targets.find(item=>item.type==='page'&&String(item.url).startsWith('http://127.0.0.1:3010'));if(!target)await delay(120);}assert.ok(target?.webSocketDebuggerUrl,'No production preview browser target');
      cdp=new CdpClient(target.webSocketDebuggerUrl);await cdp.connect();await cdp.send('Runtime.enable');
      const evaluate=async expression=>{const result=await cdp.send('Runtime.evaluate',{expression,returnByValue:true,userGesture:true,awaitPromise:true},20_000);if(result.exceptionDetails)throw new Error(result.exceptionDetails.exception?.description||result.exceptionDetails.text);return result.result?.value;};
      let opened=false;for(let attempt=0;attempt<240;attempt++){opened=await evaluate("(()=>{const opener=window.VocabMasterIeltsLauncher?.openLegacy;if(typeof opener!=='function')return false;opener('overview');return true;})()");if(opened)break;if(attempt===239)throw new Error('Production preview did not boot IELTS Lab');await delay(100);}
      const state=await evaluate(`(()=>({tabs:[...document.querySelectorAll('[data-ielts-tab]')].map(node=>node.dataset.ieltsTab),resources:performance.getEntriesByType('resource').map(entry=>entry.name),text:document.body.textContent||'',globals:Object.keys(window.VocabMasterIeltsLab||{})}))()`);
      assert.equal(state.tabs.length,7);assert.equal(state.tabs.includes('writing'),true);assert.equal(state.tabs.includes('listening-proof'),false);assert.equal(state.resources.some(url=>/(?:wave2-listening-tone-fixture\.(?:json|wav)|wave4-listening-matching-fixture\.json|wave4-reading-spatial-fixture\.json|wave4-listening-spatial-fixture\.json)/i.test(url)),false);assert.equal(state.text.includes('CONTROLLED TEST FIXTURE'),false);assert.equal(state.text.includes('Controlled Listening plan, map and diagram labelling'),false);assert.deepEqual(state.globals.sort(),['openErrorTarget','openTab']);
    }catch(error){error.message+=`\n\nPreview output:\n${serverOutput.slice(-5000)}\n\nBrowser output:\n${browserOutput.slice(-5000)}`;throw error;}finally{cdp?.close();}
  });
}

